        ordered = [segment for bucket in digit_buckets for segment in bucket]

elif op[0] == "ej":
    # 批量端点条件切换并清理旧连接：形状/字段/数量/重复 id/端点/编
    # 码、before 关系与时钟倒退已在解析期及共用时钟块判 INPUT，
    # INPUT 先于 BACKEND、BACKEND 先于 STATE。执行期先按 items 顺
