        records, saved_items
    ):
        if record["endpoint"] != target:
            record["endpoint"] = target
    index_by_id = {}
    for idx, (backend_id, _base, _target) in enumerate(saved_items):
        index_by_id[backend_id] = idx
    closed_groups = [[] for _ in saved_items]
